fn count_merge_frontier_observation(
    steps: &[AcousticCountMergeStepEvidence],
    reference_count: usize,
) -> FwResult<Option<(Option<f64>, Option<f64>)>> {
    if steps.is_empty() {
        return Ok(None);
    }
    if steps.iter().any(|step| {
        !step.same_speaker_probability.is_finite()
            || !(0.0..=1.0).contains(&step.same_speaker_probability)
    }) || !steps.windows(2).all(|window| {
        window[0].remaining_clusters.checked_sub(1) == Some(window[1].remaining_clusters)
    }) {
        return Err(public_corpus_error(
            "count_merge_frontier",
            "probabilistic count merge steps must be finite probabilities with consecutive descending cluster counts",
        ));
    }
    let probability_at = |count| {
        steps
            .iter()
            .find(|step| step.remaining_clusters == count)
            .map(|step| f64::from(step.same_speaker_probability))
    };
    Ok(Some((
        probability_at(reference_count),
        reference_count.checked_sub(1).and_then(probability_at),
    )))
}

fn hierarchy_count_candidate(
    steps: &[AcousticCountMergeStepEvidence],
    method: PublicSpeakerCountHierarchyMethod,
) -> FwResult<Option<u32>> {
    if steps.is_empty() {
        return Ok(None);
    }
    if steps.iter().any(|step| {
        !step.same_speaker_probability.is_finite()
            || !(0.0..=1.0).contains(&step.same_speaker_probability)
    }) || !steps.windows(2).all(|window| {
        window[0].remaining_clusters.checked_sub(1) == Some(window[1].remaining_clusters)
    }) {
        return Err(public_corpus_error(
            "speaker_count_hierarchy_candidate",
            "hierarchy count candidates require finite probabilities with consecutive descending cluster counts",
        ));
    }
    if method == PublicSpeakerCountHierarchyMethod::RobustSeparationThreshold {
        let initial_count = steps[0].remaining_clusters.checked_add(1).ok_or_else(|| {
            public_corpus_error(
                "speaker_count_hierarchy_candidate",
                "initial hierarchy count exceeds the supported domain",
            )
        })?;
        let candidate = steps
            .iter()
            .take_while(|step| {
                step.same_speaker_probability >= MAX_SAME_SPEAKER_PROBABILITY_FOR_SEPARATION
            })
            .last()
            .map_or(initial_count, |step| step.remaining_clusters);
        return u32::try_from(candidate).map(Some).map_err(|_| {
            public_corpus_error(
                "speaker_count_hierarchy_candidate",
                "hierarchy count candidate exceeds the public count domain",
            )
        });
    }
    if steps.len() < 2 {
        return Ok(None);
    }
    let split_index = match method {
        PublicSpeakerCountHierarchyMethod::MaximumProbabilityDrop => {
            steps
                .windows(2)
                .enumerate()
                .map(|(index, window)| {
                    (
                        index + 1,
                        f64::from(window[0].same_speaker_probability)
                            - f64::from(window[1].same_speaker_probability),
                    )
                })
                .max_by(|left, right| {
                    left.1
                        .total_cmp(&right.1)
                        .then_with(|| right.0.cmp(&left.0))
                })
                .ok_or_else(|| {
                    public_corpus_error(
                        "speaker_count_hierarchy_candidate",
                        "probability-drop candidate has no split",
                    )
                })?
                .0
        }
        PublicSpeakerCountHierarchyMethod::MaximumLogOddsDrop => {
            steps
                .windows(2)
                .enumerate()
                .map(|(index, window)| {
                    let log_odds = |probability: f32| {
                        let probability = f64::from(probability).clamp(1e-6, 1.0 - 1e-6);
                        (probability / (1.0 - probability)).ln()
                    };
                    (
                        index + 1,
                        log_odds(window[0].same_speaker_probability)
                            - log_odds(window[1].same_speaker_probability),
                    )
                })
                .max_by(|left, right| {
                    left.1
                        .total_cmp(&right.1)
                        .then_with(|| right.0.cmp(&left.0))
                })
                .ok_or_else(|| {
                    public_corpus_error(
                        "speaker_count_hierarchy_candidate",
                        "log-odds-drop candidate has no split",
                    )
                })?
                .0
        }
        PublicSpeakerCountHierarchyMethod::TwoLevelLeastSquares => {
            (1..steps.len())
                .map(|split_index| {
                    let squared_error = |slice: &[AcousticCountMergeStepEvidence]| {
                        let mean = slice
                            .iter()
                            .map(|step| f64::from(step.same_speaker_probability))
                            .sum::<f64>()
                            / slice.len() as f64;
                        slice
                            .iter()
                            .map(|step| {
                                let residual = f64::from(step.same_speaker_probability) - mean;
                                residual * residual
                            })
                            .sum::<f64>()
                    };
                    (
                        split_index,
                        squared_error(&steps[..split_index]) + squared_error(&steps[split_index..]),
                    )
                })
                .min_by(|left, right| {
                    left.1
                        .total_cmp(&right.1)
                        .then_with(|| left.0.cmp(&right.0))
                })
                .ok_or_else(|| {
                    public_corpus_error(
                        "speaker_count_hierarchy_candidate",
                        "two-level least-squares candidate has no split",
                    )
                })?
                .0
        }
        PublicSpeakerCountHierarchyMethod::RobustSeparationThreshold => {
            return Err(public_corpus_error(
                "speaker_count_hierarchy_candidate",
                "robust separation threshold reached an invalid dispatch state",
            ));
        }
    };
    u32::try_from(steps[split_index - 1].remaining_clusters)
        .map(Some)
        .map_err(|_| {
            public_corpus_error(
                "speaker_count_hierarchy_candidate",
                "hierarchy count candidate exceeds the public count domain",
            )
        })
}

