    #[test]
    fn ecapa_change_gate_requires_complete_grids_and_labels_framewise_peaks() {
        let baseline = BTreeMap::from([(800, 0.1), (900, 0.2), (1_000, 0.9), (1_100, 0.1)]);
        let replay = baseline.clone();
        let mut missing_center = baseline.clone();
        missing_center.remove(&1_000);
        assert!(!public_ecapa_change_probability_grids_match(
            &baseline,
            &missing_center,
            &replay,
        ));
        assert!(public_ecapa_change_probability_grids_match(
            &baseline, &replay, &replay,
        ));

        let evaluated_point = |boundary_ms| crate::diarization::AcousticChangeEvaluationPoint {
            evaluation_center_ms: 1_000,
            evidence: crate::diarization::ChangePointEvidence {
                boundary_ms,
                voice_distance: 1.0,
                channel_distance: 0.0,
                multiscale_scores: [1.0; 5],
                raw_log_odds: 1.0,
                change_probability: 0.75,
                supporting_scale_mask: 0b1_1111,
                refinement_offset_frames: 0,
                action: crate::diarization::AcousticChangeAction::NoBoundary,
                fallback_reason: None,
                detector_mode: crate::diarization::AcousticChangeDetectorMode::CalibratedPosterior,
                calibration_id: "test-calibration",
                silence_gap: false,
                snapped_to_word: false,
                tiny_diarize_support: false,
                vad_boundary: false,
                supervised_boundary: false,
            },
        };
        let refined_left = crate::diarization::AcousticChangeEvaluationEvidence {
            emitted: Vec::new(),
            evaluated: vec![evaluated_point(950)],
        };
        let refined_right = crate::diarization::AcousticChangeEvaluationEvidence {
            emitted: Vec::new(),
            evaluated: vec![evaluated_point(1_050)],
        };
        let refined_left_grid =
            public_ecapa_change_evaluated_probability_grid(&refined_left, 2_000);
        let refined_right_grid =
            public_ecapa_change_evaluated_probability_grid(&refined_right, 2_000);
        assert_ne!(
            refined_left.evaluated[0].evidence.boundary_ms,
            refined_right.evaluated[0].evidence.boundary_ms,
        );
        assert!(public_ecapa_change_probability_grids_match(
            &refined_left_grid,
            &refined_right_grid,
            &refined_right_grid,
        ));
        assert_eq!(
            refined_left_grid.keys().copied().collect::<Vec<_>>(),
            vec![1_000],
        );

        let observations = baseline
            .iter()
            .map(
                |(boundary_ms, probability)| super::ChangeProbabilityObservation {
                    boundary_ms: *boundary_ms,
                    probability: *probability,
                },
            )
            .collect::<Vec<_>>();
        let calibration = public_ecapa_change_frame_calibration(&[1_000], &observations, 50, 10)
            .expect("score framewise posterior calibration");
        assert_eq!(calibration.observation_count, 4);
        assert_eq!(calibration.positive_count, 1);
        assert!((calibration.brier_sum - 0.07).abs() < 1e-12);
    }

    #[test]
    #[ignore = "requires the frozen public AMI dev8 corpus and converted ECAPA weights"]
    fn external_ecapa_change_detector_same_invocation_development_gate() {
        let fixture = load_frozen_ecapa_dev8();
        let policy = public_ecapa_change_gate_policy();
        let policy_sha256 =
            super::canonical_sha256(&policy).expect("hash frozen ECAPA change gate policy");
        let protocol_sha256 = public_ecapa_change_protocol_sha256(&fixture, &policy_sha256);
        let engines = [
            crate::model::DiarizationEngine::Ecapa,
            crate::model::DiarizationEngine::EcapaFused,
        ];
        let mut rows = Vec::with_capacity(
            usize::try_from(PUBLIC_ECAPA_CHANGE_REQUIRED_PAIR_ROWS).expect("pair count fits usize"),
        );
        let mut expected_bindings = Vec::with_capacity(rows.capacity());
        let mut expected_outputs = Vec::with_capacity(rows.capacity());
        let mut memory_observation = PublicEcapaResidualBirthMemoryObservation::new();
        let mut arm_execution_failure_count = 0_u64;
        memory_observation.observe_stage();

        for recording_index in 0..fixture.bundle.references.len() {
            let recording = load_frozen_ecapa_recording(&fixture, recording_index);
            for (engine_index, engine) in engines.iter().copied().enumerate() {
                let (request, evidence_mode) = frozen_ecapa_request(engine);
                let input_binding = public_ecapa_change_input_binding(
                    &fixture,
                    &recording,
                    &request,
                    evidence_mode,
                );
                expected_bindings.push(input_binding.clone());
                let pair_index = recording_index
                    .saturating_mul(engines.len())
                    .saturating_add(engine_index);
                let execution_order = public_ecapa_execution_order(pair_index);
                let (baseline, candidate) = match execution_order {
                    PublicEcapaResidualBirthExecutionOrder::BaselineThenCandidate => (
                        catch_public_ecapa_change_arm_failure(
                            &fixture,
                            &recording,
                            &request,
                            crate::diarization::AcousticChangeDetectorMode::FixedSafeV1,
                            &mut memory_observation,
                            &mut arm_execution_failure_count,
                        ),
                        catch_public_ecapa_change_arm_failure(
                            &fixture,
                            &recording,
                            &request,
                            crate::diarization::AcousticChangeDetectorMode::CalibratedPosterior,
                            &mut memory_observation,
                            &mut arm_execution_failure_count,
                        ),
                    ),
                    PublicEcapaResidualBirthExecutionOrder::CandidateThenBaseline => {
                        let candidate = catch_public_ecapa_change_arm_failure(
                            &fixture,
                            &recording,
                            &request,
                            crate::diarization::AcousticChangeDetectorMode::CalibratedPosterior,
                            &mut memory_observation,
                            &mut arm_execution_failure_count,
                        );
                        let baseline = catch_public_ecapa_change_arm_failure(
                            &fixture,
                            &recording,
                            &request,
                            crate::diarization::AcousticChangeDetectorMode::FixedSafeV1,
                            &mut memory_observation,
                            &mut arm_execution_failure_count,
                        );
                        (baseline, candidate)
                    }
                };
                let candidate_replay = catch_public_ecapa_change_arm_failure(
                    &fixture,
                    &recording,
                    &request,
                    crate::diarization::AcousticChangeDetectorMode::CalibratedPosterior,
                    &mut memory_observation,
                    &mut arm_execution_failure_count,
                );
                let (Some(baseline), Some(candidate), Some(candidate_replay)) =
                    (baseline, candidate, candidate_replay)
                else {
                    continue;
                };
                let (row, expected_output) = public_ecapa_change_pair_row(
                    &fixture,
                    &recording,
                    engine,
                    input_binding,
                    &protocol_sha256,
                    execution_order,
                    baseline,
                    candidate,
                    candidate_replay,
                );
                expected_outputs.push(expected_output);
                let serialized = serialize_path_free_public_ecapa_evidence(
                    &row,
                    &[
                        &fixture.descriptor_path,
                        &fixture.weight_path,
                        &fixture.input_root,
                        &recording.audio_path,
                    ],
                );
                println!("{serialized}");
                rows.push(row);
            }
        }

        if arm_execution_failure_count == 0 {
            assert_eq!(rows.len() as u64, PUBLIC_ECAPA_CHANGE_REQUIRED_PAIR_ROWS);
        }
        let gate = public_ecapa_change_gate_row(
            &fixture,
            &rows,
            &expected_bindings,
            &expected_outputs,
            policy.clone(),
            policy_sha256.clone(),
            protocol_sha256.clone(),
            arm_execution_failure_count,
            &memory_observation,
        );
        assert_eq!(
            gate.result_sha256,
            public_ecapa_change_gate_result_sha256(&gate)
        );
        let serialized = serialize_path_free_public_ecapa_evidence(
            &gate,
            &[
                &fixture.descriptor_path,
                &fixture.weight_path,
                &fixture.input_root,
            ],
        );
        println!("{serialized}");

        if arm_execution_failure_count == 0
            && rows.len() as u64 == PUBLIC_ECAPA_CHANGE_REQUIRED_PAIR_ROWS
        {
            let mut weakened_policy = policy.clone();
            weakened_policy.minimum_relative_detector_f1_improvement = 0.0;
            let weakened_policy_sha256 = super::canonical_sha256(&weakened_policy)
                .expect("hash weakened ECAPA change policy");
            let weakened_protocol_sha256 =
                public_ecapa_change_protocol_sha256(&fixture, &weakened_policy_sha256);
            let weakened_gate = public_ecapa_change_gate_row(
                &fixture,
                &rows,
                &expected_bindings,
                &expected_outputs,
                weakened_policy,
                weakened_policy_sha256,
                weakened_protocol_sha256,
                arm_execution_failure_count,
                &memory_observation,
            );
            assert!(!weakened_gate.passed);
            assert!(
                weakened_gate
                    .failures
                    .contains(&PublicEcapaChangeGateFailure::PolicyHashMismatch)
            );

            let dropped_row_gate = public_ecapa_change_gate_row(
                &fixture,
                &rows[..rows.len() - 1],
                &expected_bindings,
                &expected_outputs,
                policy.clone(),
                policy_sha256.clone(),
                protocol_sha256.clone(),
                arm_execution_failure_count,
                &memory_observation,
            );
            assert!(!dropped_row_gate.passed);
            assert!(
                dropped_row_gate
                    .failures
                    .contains(&PublicEcapaChangeGateFailure::PairCountMismatch)
            );

            let mut balanced_order_tamper = rows.clone();
            let first_order = balanced_order_tamper[0].timing.execution_order;
            let second_order = balanced_order_tamper[2].timing.execution_order;
            balanced_order_tamper[0].timing.execution_order = second_order;
            balanced_order_tamper[2].timing.execution_order = first_order;
            balanced_order_tamper[0].deterministic_accuracy_sha256 =
                public_ecapa_change_pair_accuracy_sha256(&balanced_order_tamper[0]);
            balanced_order_tamper[0].row_sha256 =
                public_ecapa_change_pair_result_sha256(&balanced_order_tamper[0]);
            balanced_order_tamper[2].deterministic_accuracy_sha256 =
                public_ecapa_change_pair_accuracy_sha256(&balanced_order_tamper[2]);
            balanced_order_tamper[2].row_sha256 =
                public_ecapa_change_pair_result_sha256(&balanced_order_tamper[2]);
            let balanced_order_gate = public_ecapa_change_gate_row(
                &fixture,
                &balanced_order_tamper,
                &expected_bindings,
                &expected_outputs,
                policy.clone(),
                policy_sha256.clone(),
                protocol_sha256.clone(),
                arm_execution_failure_count,
                &memory_observation,
            );
            assert!(!balanced_order_gate.passed);
            assert!(
                balanced_order_gate
                    .failures
                    .contains(&PublicEcapaChangeGateFailure::PairIntegrityMismatch)
            );

            let mut timing_authority_tamper = rows.clone();
            timing_authority_tamper[0].timing.baseline_wall_ns = u64::MAX / 2;
            timing_authority_tamper[0].timing.candidate_wall_ns = 1;
            timing_authority_tamper[0].deterministic_accuracy_sha256 =
                public_ecapa_change_pair_accuracy_sha256(&timing_authority_tamper[0]);
            timing_authority_tamper[0].row_sha256 =
                public_ecapa_change_pair_result_sha256(&timing_authority_tamper[0]);
            let timing_authority_gate = public_ecapa_change_gate_row(
                &fixture,
                &timing_authority_tamper,
                &expected_bindings,
                &expected_outputs,
                policy.clone(),
                policy_sha256.clone(),
                protocol_sha256.clone(),
                arm_execution_failure_count,
                &memory_observation,
            );
            assert!(!timing_authority_gate.passed);
            assert!(
                timing_authority_gate
                    .failures
                    .contains(&PublicEcapaChangeGateFailure::OutputAuthorityMismatch)
            );

            let mut output_authority_tamper = rows.clone();
            output_authority_tamper[0].candidate.report_sha256 = "f".repeat(64);
            output_authority_tamper[0]
                .comparison
                .candidate_replay_report_sha256 = "f".repeat(64);
            output_authority_tamper[0].deterministic_accuracy_sha256 =
                public_ecapa_change_pair_accuracy_sha256(&output_authority_tamper[0]);
            output_authority_tamper[0].row_sha256 =
                public_ecapa_change_pair_result_sha256(&output_authority_tamper[0]);
            let output_authority_gate = public_ecapa_change_gate_row(
                &fixture,
                &output_authority_tamper,
                &expected_bindings,
                &expected_outputs,
                policy.clone(),
                policy_sha256.clone(),
                protocol_sha256.clone(),
                arm_execution_failure_count,
                &memory_observation,
            );
            assert!(!output_authority_gate.passed);
            assert!(
                output_authority_gate
                    .failures
                    .contains(&PublicEcapaChangeGateFailure::OutputAuthorityMismatch)
            );

            let mut comparison_tamper = rows.clone();
            comparison_tamper[0].comparison.unknown_share_non_regression =
                !comparison_tamper[0].comparison.unknown_share_non_regression;
            comparison_tamper[0].deterministic_accuracy_sha256 =
                public_ecapa_change_pair_accuracy_sha256(&comparison_tamper[0]);
            comparison_tamper[0].row_sha256 =
                public_ecapa_change_pair_result_sha256(&comparison_tamper[0]);
            let comparison_gate = public_ecapa_change_gate_row(
                &fixture,
                &comparison_tamper,
                &expected_bindings,
                &expected_outputs,
                policy.clone(),
                policy_sha256.clone(),
                protocol_sha256.clone(),
                arm_execution_failure_count,
                &memory_observation,
            );
            assert!(!comparison_gate.passed);
            assert!(
                comparison_gate
                    .failures
                    .contains(&PublicEcapaChangeGateFailure::PairIntegrityMismatch)
            );

            let mut malformed_calibration = rows.clone();
            malformed_calibration[0].candidate.calibration.bins.pop();
            malformed_calibration[0].deterministic_accuracy_sha256 =
                public_ecapa_change_pair_accuracy_sha256(&malformed_calibration[0]);
            malformed_calibration[0].row_sha256 =
                public_ecapa_change_pair_result_sha256(&malformed_calibration[0]);
            let malformed_calibration_gate = public_ecapa_change_gate_row(
                &fixture,
                &malformed_calibration,
                &expected_bindings,
                &expected_outputs,
                policy.clone(),
                policy_sha256.clone(),
                protocol_sha256.clone(),
                arm_execution_failure_count,
                &memory_observation,
            );
            assert!(!malformed_calibration_gate.passed);
            assert!(
                malformed_calibration_gate
                    .failures
                    .contains(&PublicEcapaChangeGateFailure::TopologyResourceExceeded)
            );

            let incomplete_memory = PublicEcapaResidualBirthMemoryObservation::new();
            let incomplete_memory_gate = public_ecapa_change_gate_row(
                &fixture,
                &rows,
                &expected_bindings,
                &expected_outputs,
                policy.clone(),
                policy_sha256.clone(),
                protocol_sha256.clone(),
                arm_execution_failure_count,
                &incomplete_memory,
            );
            assert!(!incomplete_memory_gate.passed);
            assert!(
                incomplete_memory_gate
                    .failures
                    .contains(&PublicEcapaChangeGateFailure::MissingAuthoritativeRss)
            );
        }
        assert!(
            gate.passed,
            "ECAPA change-detector candidate did not pass its frozen public-development gate: {:?}",
            gate.failures
        );
    }

    #[test]
    #[ignore = "requires the frozen public AMI dev8 corpus and converted ECAPA weights"]
    fn external_ecapa_residual_birth_same_invocation_development_gate() {
        let fixture = load_frozen_ecapa_dev8();
        let gate_policy = public_ecapa_residual_birth_gate_policy();
        let gate_policy_sha256 =
            super::canonical_sha256(&gate_policy).expect("hash residual-birth gate policy");
        let residual_policy_sha256 = crate::diarization::ecapa_residual_birth_policy_sha256();
        let protocol_sha256 = public_ecapa_residual_birth_protocol_sha256(
            &fixture,
            &residual_policy_sha256,
            &gate_policy_sha256,
        );
        let baseline_variant_configuration_sha256 =
            super::canonical_sha256(&crate::diarization::ECAPA_RESIDUAL_BIRTH_BASELINE_VERSION)
                .expect("hash incumbent ECAPA variant");
        let engines = [
            crate::model::DiarizationEngine::Ecapa,
            crate::model::DiarizationEngine::EcapaFused,
        ];
        let mut rows = Vec::with_capacity(PUBLIC_ECAPA_RESIDUAL_REQUIRED_PAIR_ROWS as usize);
        let mut expected_common_observations =
            Vec::with_capacity(PUBLIC_ECAPA_RESIDUAL_REQUIRED_PAIR_ROWS as usize);
        let mut memory_observation = PublicEcapaResidualBirthMemoryObservation::new();
        memory_observation.observe_stage();

        for recording_index in 0..fixture.bundle.references.len() {
            let recording = load_frozen_ecapa_recording(&fixture, recording_index);
            for (engine_index, engine) in engines.iter().copied().enumerate() {
                let (request, evidence_mode) = frozen_ecapa_request(engine);
                let preparation_started = std::time::Instant::now();
                let prepared = crate::diarization::prepare_ecapa_diarization_evaluation(
                    crate::diarization::AcousticDiarizationInput {
                        samples: &recording.samples,
                        normalized_input_sha256: &recording.normalized_input_sha256,
                        segments: &[],
                        word_aligned: false,
                        request: &request,
                        boundary_hints: &recording.boundary_hints,
                    },
                    &fixture.model,
                    &|| Ok(()),
                )
                .expect("prepare one common ECAPA observation set");
                let common_preparation_wall_ns =
                    public_ecapa_duration_ns(preparation_started.elapsed());
                memory_observation.observe_stage();
                let pair_index = recording_index
                    .saturating_mul(engines.len())
                    .saturating_add(engine_index);
                let execution_order = public_ecapa_execution_order(pair_index);
                let (
                    (baseline_run, baseline_partition_finish_wall_ns),
                    (candidate_run, candidate_partition_finish_wall_ns),
                ) = match execution_order {
                    PublicEcapaResidualBirthExecutionOrder::BaselineThenCandidate => (
                        run_prepared_public_ecapa_arm(
                            &prepared,
                            crate::diarization::EcapaResidualBirthMode::DisabledIncumbent,
                            &mut memory_observation,
                        ),
                        run_prepared_public_ecapa_arm(
                            &prepared,
                            crate::diarization::EcapaResidualBirthMode::DevelopmentCandidateV1,
                            &mut memory_observation,
                        ),
                    ),
                    PublicEcapaResidualBirthExecutionOrder::CandidateThenBaseline => {
                        let candidate = run_prepared_public_ecapa_arm(
                            &prepared,
                            crate::diarization::EcapaResidualBirthMode::DevelopmentCandidateV1,
                            &mut memory_observation,
                        );
                        let baseline = run_prepared_public_ecapa_arm(
                            &prepared,
                            crate::diarization::EcapaResidualBirthMode::DisabledIncumbent,
                            &mut memory_observation,
                        );
                        (baseline, candidate)
                    }
                };
                let (candidate_replay_run, candidate_replay_wall_ns) =
                    run_prepared_public_ecapa_arm(
                        &prepared,
                        crate::diarization::EcapaResidualBirthMode::DevelopmentCandidateV1,
                        &mut memory_observation,
                    );

                let prepared_common_observation_sha256 = prepared.common_observation_sha256();
                for (run, expected_mode) in [
                    (
                        &baseline_run,
                        crate::diarization::EcapaResidualBirthMode::DisabledIncumbent,
                    ),
                    (
                        &candidate_run,
                        crate::diarization::EcapaResidualBirthMode::DevelopmentCandidateV1,
                    ),
                    (
                        &candidate_replay_run,
                        crate::diarization::EcapaResidualBirthMode::DevelopmentCandidateV1,
                    ),
                ] {
                    run.report
                        .validate_against_request(&request, Some(recording.reference.duration_ms))
                        .expect("valid request-bound paired ECAPA report");
                    assert_eq!(run.report.speaker_evidence_mode, evidence_mode);
                    assert_eq!(
                        run.report.normalized_input_sha256,
                        recording.normalized_input_sha256
                    );
                    assert_eq!(
                        run.common_observation_sha256,
                        prepared_common_observation_sha256
                    );
                    assert_eq!(
                        run.residual_birth.common_observation_sha256,
                        prepared_common_observation_sha256
                    );
                    assert_eq!(run.policy_sha256, residual_policy_sha256);
                    assert_eq!(run.residual_birth.policy_sha256, residual_policy_sha256);
                    assert_eq!(run.residual_birth.mode, expected_mode);
                    assert_eq!(
                        run.residual_birth.schema_version,
                        crate::diarization::ECAPA_RESIDUAL_BIRTH_EVIDENCE_SCHEMA_VERSION
                    );
                    let representation = run
                        .report
                        .neural_representation
                        .as_ref()
                        .expect("paired ECAPA report retains neural representation provenance");
                    assert_eq!(
                        representation.provider_version,
                        crate::diarization::ECAPA_SPEAKER_REPRESENTATION_VERSION
                    );
                    assert_eq!(
                        representation.loaded_model_package_sha256.as_deref(),
                        Some(crate::ecapa_conformance::ECAPA_PACKAGE_SHA256)
                    );
                    assert_eq!(
                        representation.expected_model_package_sha256,
                        crate::ecapa_conformance::ECAPA_PACKAGE_SHA256
                    );
                    assert_eq!(
                        representation.embedded_tracklet_count,
                        prepared.embedded_tracklet_count()
                    );
                    let count_estimate = run
                        .report
                        .speaker_count
                        .estimate
                        .as_ref()
                        .expect("paired ECAPA report retains count evidence");
                    assert_eq!(
                        count_estimate.calibration_sha256,
                        crate::diarization::ecapa_speaker_pair_calibration_sha256(evidence_mode)
                    );
                }

                let baseline_score = score_path_free_ecapa_report(
                    recording.reference,
                    &baseline_run.report,
                    &fixture.scorer_config,
                );
                let candidate_score = score_path_free_ecapa_report(
                    recording.reference,
                    &candidate_run.report,
                    &fixture.scorer_config,
                );
                let candidate_replay_score = score_path_free_ecapa_report(
                    recording.reference,
                    &candidate_replay_run.report,
                    &fixture.scorer_config,
                );
                for score in [&baseline_score, &candidate_score, &candidate_replay_score] {
                    assert_eq!(score.recording_id, recording.reference.recording_id);
                    assert_eq!(score.config_sha256, fixture.scorer_config_sha256);
                }

                let baseline = public_ecapa_residual_birth_arm_row(
                    &baseline_run,
                    &baseline_score,
                    "disabled_incumbent",
                    &baseline_variant_configuration_sha256,
                );
                let candidate = public_ecapa_residual_birth_arm_row(
                    &candidate_run,
                    &candidate_score,
                    "development_candidate_v1",
                    &residual_policy_sha256,
                );
                let candidate_replay_report_sha256 =
                    super::canonical_sha256(&candidate_replay_run.report)
                        .expect("hash candidate replay report");
                let candidate_replay_residual_birth_evidence_sha256 =
                    super::canonical_sha256(&candidate_replay_run.residual_birth)
                        .expect("hash candidate replay residual-birth evidence");
                let candidate_replay_structural_output_matches =
                    crate::diarization::prepared_ecapa_evaluation_outputs_identical(
                        &candidate_run,
                        &candidate_replay_run,
                    );
                let candidate_replay_matches = candidate_replay_structural_output_matches
                    && candidate_replay_report_sha256 == candidate.report_sha256
                    && candidate_replay_residual_birth_evidence_sha256
                        == candidate.residual_birth_evidence_sha256
                    && candidate_replay_score.result_sha256 == candidate_score.result_sha256
                    && candidate_replay_run.common_observation_sha256
                        == candidate_run.common_observation_sha256;
                let rejected_candidate_structural_output_matches_incumbent =
                    !candidate_run.residual_birth.birth_applied
                        && crate::diarization::prepared_ecapa_evaluation_outputs_identical(
                            &baseline_run,
                            &candidate_run,
                        );
                let pair_alignment_matches = baseline_score.recording_id
                    == candidate_score.recording_id
                    && baseline_score.reference_sha256 == candidate_score.reference_sha256
                    && baseline_score.config_sha256 == candidate_score.config_sha256;
                let common_observation_matches = baseline_run.common_observation_sha256
                    == candidate_run.common_observation_sha256
                    && candidate_run.common_observation_sha256
                        == candidate_replay_run.common_observation_sha256
                    && candidate_replay_run.common_observation_sha256
                        == prepared_common_observation_sha256;
                let incumbent_contract_matches = baseline_run.residual_birth.mode
                    == crate::diarization::EcapaResidualBirthMode::DisabledIncumbent
                    && !baseline_run.residual_birth.birth_applied
                    && baseline_run.residual_birth.proposal_kind.is_none()
                    && baseline_run.residual_birth.fallback_reason
                        == Some(
                            crate::diarization::EcapaResidualBirthFallbackReason::DisabledIncumbent,
                        )
                    && baseline_run.residual_birth.incumbent_cluster_count
                        == baseline_run.residual_birth.output_cluster_count;
                let comparison = public_ecapa_pair_comparison(
                    &baseline,
                    &candidate,
                    candidate_replay_report_sha256,
                    candidate_replay_run.common_observation_sha256.clone(),
                    candidate_replay_residual_birth_evidence_sha256,
                    candidate_replay_score.result_sha256.clone(),
                    candidate_replay_structural_output_matches,
                    candidate_replay_matches,
                    rejected_candidate_structural_output_matches_incumbent,
                    pair_alignment_matches,
                    common_observation_matches,
                    incumbent_contract_matches,
                );
                let common_observation = PublicEcapaCommonObservationBinding {
                    common_observation_schema:
                        PUBLIC_ECAPA_COMMON_OBSERVATION_BINDING_SCHEMA_VERSION.to_owned(),
                    common_observation_sha256: prepared_common_observation_sha256.to_owned(),
                    source_audio_sha256: recording.source_audio_sha256.clone(),
                    normalized_input_sha256: recording.normalized_input_sha256.clone(),
                    feature_schema_version: crate::diarization::ACOUSTIC_FEATURE_SCHEMA_VERSION
                        .to_owned(),
                    ecapa_contract_sha256: crate::ecapa_conformance::ECAPA_CONTRACT_SHA256
                        .to_owned(),
                    ecapa_package_sha256: crate::ecapa_conformance::ECAPA_PACKAGE_SHA256.to_owned(),
                    representation_provider_version:
                        crate::diarization::ECAPA_SPEAKER_REPRESENTATION_VERSION.to_owned(),
                    embedded_tracklet_count: prepared.embedded_tracklet_count(),
                };
                expected_common_observations.push(common_observation.clone());
                let mut row = PublicEcapaResidualBirthPairRow {
                    schema_version: PUBLIC_ECAPA_RESIDUAL_PAIR_SCHEMA_VERSION.to_owned(),
                    protocol_sha256: protocol_sha256.clone(),
                    corpus_key: fixture.bundle.corpus_key.clone(),
                    source_version: fixture.bundle.source_version.clone(),
                    evaluation_split: EvaluationSplit::Development,
                    recording_id: recording.reference.recording_id.clone(),
                    audio_duration_ms: recording.reference.duration_ms,
                    engine,
                    evidence_mode,
                    common_observation,
                    baseline,
                    candidate,
                    comparison,
                    timing: PublicEcapaResidualBirthPairTiming {
                        common_preparation_wall_ns,
                        baseline_partition_finish_wall_ns,
                        candidate_partition_finish_wall_ns,
                        candidate_replay_wall_ns,
                        execution_order,
                        candidate_replay_excluded_from_gate: true,
                    },
                    deterministic_accuracy_sha256: String::new(),
                    row_sha256: String::new(),
                };
                row.deterministic_accuracy_sha256 = public_ecapa_pair_accuracy_sha256(&row);
                row.row_sha256 = public_ecapa_pair_result_sha256(&row);
                let serialized = serialize_path_free_public_ecapa_evidence(
                    &row,
                    &[
                        &fixture.descriptor_path,
                        &fixture.weight_path,
                        &fixture.input_root,
                        &recording.audio_path,
                    ],
                );
                println!("{serialized}");
                rows.push(row);
            }
        }

        let dropped_gate = public_ecapa_residual_birth_gate_row(
            &fixture,
            &rows[..rows.len().saturating_sub(1)],
            &expected_common_observations,
            &residual_policy_sha256,
            &protocol_sha256,
            gate_policy.clone(),
            gate_policy_sha256.clone(),
            &memory_observation,
        );
        assert!(!dropped_gate.passed);
        assert!(
            dropped_gate
                .failures
                .contains(&PublicEcapaResidualBirthGateFailure::PairCountMismatch)
        );

        let mut misaligned_rows = rows.clone();
        misaligned_rows.swap(0, 1);
        let misaligned_gate = public_ecapa_residual_birth_gate_row(
            &fixture,
            &misaligned_rows,
            &expected_common_observations,
            &residual_policy_sha256,
            &protocol_sha256,
            gate_policy.clone(),
            gate_policy_sha256.clone(),
            &memory_observation,
        );
        assert!(!misaligned_gate.passed);
        assert!(
            misaligned_gate
                .failures
                .contains(&PublicEcapaResidualBirthGateFailure::PairAlignmentMismatch)
        );

        let mut timing_tampered_rows = rows.clone();
        timing_tampered_rows[0]
            .timing
            .candidate_replay_excluded_from_gate = false;
        timing_tampered_rows[0].row_sha256 =
            public_ecapa_pair_result_sha256(&timing_tampered_rows[0]);
        let timing_tampered_gate = public_ecapa_residual_birth_gate_row(
            &fixture,
            &timing_tampered_rows,
            &expected_common_observations,
            &residual_policy_sha256,
            &protocol_sha256,
            gate_policy.clone(),
            gate_policy_sha256.clone(),
            &memory_observation,
        );
        assert!(!timing_tampered_gate.passed);
        assert!(
            timing_tampered_gate
                .failures
                .contains(&PublicEcapaResidualBirthGateFailure::PairIntegrityMismatch)
        );

        let mut metric_tampered_rows = rows.clone();
        metric_tampered_rows[0]
            .baseline
            .accuracy
            .exact_speaker_count = !metric_tampered_rows[0]
            .baseline
            .accuracy
            .exact_speaker_count;
        metric_tampered_rows[0].deterministic_accuracy_sha256 =
            public_ecapa_pair_accuracy_sha256(&metric_tampered_rows[0]);
        metric_tampered_rows[0].row_sha256 =
            public_ecapa_pair_result_sha256(&metric_tampered_rows[0]);
        let metric_tampered_gate = public_ecapa_residual_birth_gate_row(
            &fixture,
            &metric_tampered_rows,
            &expected_common_observations,
            &residual_policy_sha256,
            &protocol_sha256,
            gate_policy.clone(),
            gate_policy_sha256.clone(),
            &memory_observation,
        );
        assert!(!metric_tampered_gate.passed);
        assert!(
            metric_tampered_gate
                .failures
                .contains(&PublicEcapaResidualBirthGateFailure::PairIntegrityMismatch)
        );

        let mut comparison_tampered_rows = rows.clone();
        let tampered_der_delta = comparison_tampered_rows[0]
            .comparison
            .der_delta
            .unwrap_or(0.0)
            + 1.0;
        comparison_tampered_rows[0].comparison.der_delta = Some(tampered_der_delta);
        comparison_tampered_rows[0].deterministic_accuracy_sha256 =
            public_ecapa_pair_accuracy_sha256(&comparison_tampered_rows[0]);
        comparison_tampered_rows[0].row_sha256 =
            public_ecapa_pair_result_sha256(&comparison_tampered_rows[0]);
        let comparison_tampered_gate = public_ecapa_residual_birth_gate_row(
            &fixture,
            &comparison_tampered_rows,
            &expected_common_observations,
            &residual_policy_sha256,
            &protocol_sha256,
            gate_policy.clone(),
            gate_policy_sha256.clone(),
            &memory_observation,
        );
        assert!(!comparison_tampered_gate.passed);
        assert!(
            comparison_tampered_gate
                .failures
                .contains(&PublicEcapaResidualBirthGateFailure::PairIntegrityMismatch)
        );

        let mut parity_tampered_rows = rows.clone();
        parity_tampered_rows[0].timing.execution_order =
            PublicEcapaResidualBirthExecutionOrder::CandidateThenBaseline;
        parity_tampered_rows[1].timing.execution_order =
            PublicEcapaResidualBirthExecutionOrder::BaselineThenCandidate;
        for row in &mut parity_tampered_rows[..2] {
            row.row_sha256 = public_ecapa_pair_result_sha256(row);
        }
        let parity_tampered_gate = public_ecapa_residual_birth_gate_row(
            &fixture,
            &parity_tampered_rows,
            &expected_common_observations,
            &residual_policy_sha256,
            &protocol_sha256,
            gate_policy.clone(),
            gate_policy_sha256.clone(),
            &memory_observation,
        );
        assert!(!parity_tampered_gate.passed);
        assert!(
            parity_tampered_gate
                .failures
                .contains(&PublicEcapaResidualBirthGateFailure::PairIntegrityMismatch)
        );

        let mut balance_tampered_rows = rows.clone();
        balance_tampered_rows[0].timing.execution_order =
            PublicEcapaResidualBirthExecutionOrder::CandidateThenBaseline;
        balance_tampered_rows[0].row_sha256 =
            public_ecapa_pair_result_sha256(&balance_tampered_rows[0]);
        let balance_tampered_gate = public_ecapa_residual_birth_gate_row(
            &fixture,
            &balance_tampered_rows,
            &expected_common_observations,
            &residual_policy_sha256,
            &protocol_sha256,
            gate_policy.clone(),
            gate_policy_sha256.clone(),
            &memory_observation,
        );
        assert!(!balance_tampered_gate.passed);
        assert!(
            balance_tampered_gate
                .failures
                .contains(&PublicEcapaResidualBirthGateFailure::PairIntegrityMismatch)
        );

        let mut operation_tampered_rows = rows.clone();
        operation_tampered_rows[0]
            .candidate
            .resources
            .operation_count = gate_policy
            .maximum_operation_count_per_pair
            .saturating_add(1);
        operation_tampered_rows[0]
            .candidate
            .resources
            .cancellation_check_count = public_ecapa_expected_cancellation_checks(
            operation_tampered_rows[0]
                .candidate
                .resources
                .operation_count,
            gate_policy.cancellation_check_interval_operations,
        )
        .expect("frozen cancellation cadence is defined");
        operation_tampered_rows[0].row_sha256 =
            public_ecapa_pair_result_sha256(&operation_tampered_rows[0]);
        let operation_tampered_gate = public_ecapa_residual_birth_gate_row(
            &fixture,
            &operation_tampered_rows,
            &expected_common_observations,
            &residual_policy_sha256,
            &protocol_sha256,
            gate_policy.clone(),
            gate_policy_sha256.clone(),
            &memory_observation,
        );
        assert!(!operation_tampered_gate.passed);
        assert!(
            operation_tampered_gate
                .failures
                .contains(&PublicEcapaResidualBirthGateFailure::ResourceBoundExceeded)
        );

        let mut cancellation_tampered_rows = rows.clone();
        cancellation_tampered_rows[0]
            .candidate
            .resources
            .cancellation_check_count = cancellation_tampered_rows[0]
            .candidate
            .resources
            .cancellation_check_count
            .saturating_add(1);
        cancellation_tampered_rows[0].row_sha256 =
            public_ecapa_pair_result_sha256(&cancellation_tampered_rows[0]);
        let cancellation_tampered_gate = public_ecapa_residual_birth_gate_row(
            &fixture,
            &cancellation_tampered_rows,
            &expected_common_observations,
            &residual_policy_sha256,
            &protocol_sha256,
            gate_policy.clone(),
            gate_policy_sha256.clone(),
            &memory_observation,
        );
        assert!(!cancellation_tampered_gate.passed);
        assert!(
            cancellation_tampered_gate
                .failures
                .contains(&PublicEcapaResidualBirthGateFailure::ResourceBoundExceeded)
        );

        let mut robust_view_tampered_rows = rows.clone();
        let robust_view_bound =
            public_ecapa_robust_view_comparison_bound(&robust_view_tampered_rows[0], &gate_policy)
                .expect("frozen robust-view bound is defined");
        robust_view_tampered_rows[0]
            .candidate
            .resources
            .robust_view_comparison_count = robust_view_bound.saturating_add(1);
        let resources = &mut robust_view_tampered_rows[0].candidate.resources;
        resources.operation_count = resources.operation_count.max(
            resources
                .parent_count_scanned
                .saturating_add(resources.residual_observation_count)
                .saturating_add(resources.leave_pair_out_pair_count)
                .saturating_add(resources.lloyd_assignment_visits)
                .saturating_add(resources.robust_view_comparison_count),
        );
        resources.cancellation_check_count = public_ecapa_expected_cancellation_checks(
            resources.operation_count,
            gate_policy.cancellation_check_interval_operations,
        )
        .expect("frozen cancellation cadence is defined");
        robust_view_tampered_rows[0].row_sha256 =
            public_ecapa_pair_result_sha256(&robust_view_tampered_rows[0]);
        let robust_view_tampered_gate = public_ecapa_residual_birth_gate_row(
            &fixture,
            &robust_view_tampered_rows,
            &expected_common_observations,
            &residual_policy_sha256,
            &protocol_sha256,
            gate_policy.clone(),
            gate_policy_sha256.clone(),
            &memory_observation,
        );
        assert!(!robust_view_tampered_gate.passed);
        assert!(
            robust_view_tampered_gate
                .failures
                .contains(&PublicEcapaResidualBirthGateFailure::ResourceBoundExceeded)
        );

        let mut misrouted_ecapa_rows = rows.clone();
        assert_eq!(
            misrouted_ecapa_rows[0].engine,
            crate::model::DiarizationEngine::Ecapa
        );
        misrouted_ecapa_rows[0].candidate.fallback_reason =
            Some(crate::diarization::EcapaResidualBirthFallbackReason::IncumbentNotEcapaSpherical);
        misrouted_ecapa_rows[0].deterministic_accuracy_sha256 =
            public_ecapa_pair_accuracy_sha256(&misrouted_ecapa_rows[0]);
        misrouted_ecapa_rows[0].row_sha256 =
            public_ecapa_pair_result_sha256(&misrouted_ecapa_rows[0]);
        let misrouted_ecapa_gate = public_ecapa_residual_birth_gate_row(
            &fixture,
            &misrouted_ecapa_rows,
            &expected_common_observations,
            &residual_policy_sha256,
            &protocol_sha256,
            gate_policy.clone(),
            gate_policy_sha256.clone(),
            &memory_observation,
        );
        assert!(!misrouted_ecapa_gate.passed);
        assert!(
            misrouted_ecapa_gate
                .failures
                .contains(&PublicEcapaResidualBirthGateFailure::CandidateEligibilityMismatch)
        );

        let weakened_residual_policy_sha256 = "0".repeat(64);
        assert_ne!(
            weakened_residual_policy_sha256, residual_policy_sha256,
            "adversarial residual policy must differ from the frozen runtime policy"
        );
        let weakened_residual_protocol_sha256 = public_ecapa_residual_birth_protocol_sha256(
            &fixture,
            &weakened_residual_policy_sha256,
            &gate_policy_sha256,
        );
        let mut weakened_residual_rows = rows.clone();
        for row in &mut weakened_residual_rows {
            row.protocol_sha256 = weakened_residual_protocol_sha256.clone();
            row.candidate.variant_configuration_sha256 = weakened_residual_policy_sha256.clone();
            row.deterministic_accuracy_sha256 = public_ecapa_pair_accuracy_sha256(row);
            row.row_sha256 = public_ecapa_pair_result_sha256(row);
        }
        let weakened_residual_gate = public_ecapa_residual_birth_gate_row(
            &fixture,
            &weakened_residual_rows,
            &expected_common_observations,
            &weakened_residual_policy_sha256,
            &weakened_residual_protocol_sha256,
            gate_policy.clone(),
            gate_policy_sha256.clone(),
            &memory_observation,
        );
        assert!(!weakened_residual_gate.passed);
        assert!(
            weakened_residual_gate
                .failures
                .contains(&PublicEcapaResidualBirthGateFailure::ResidualPolicyMismatch)
        );

        let mut weakened_policy = gate_policy.clone();
        weakened_policy.minimum_exact_match_gain = 0;
        weakened_policy.require_strict_micro_der_improvement = false;
        let weakened_policy_sha256 =
            super::canonical_sha256(&weakened_policy).expect("hash weakened gate probe");
        let weakened_protocol_sha256 = public_ecapa_residual_birth_protocol_sha256(
            &fixture,
            &residual_policy_sha256,
            &weakened_policy_sha256,
        );
        let weakened_gate = public_ecapa_residual_birth_gate_row(
            &fixture,
            &rows,
            &expected_common_observations,
            &residual_policy_sha256,
            &weakened_protocol_sha256,
            weakened_policy,
            weakened_policy_sha256,
            &memory_observation,
        );
        assert!(!weakened_gate.passed);
        assert!(
            weakened_gate
                .failures
                .contains(&PublicEcapaResidualBirthGateFailure::PolicyHashMismatch)
        );

        let gate = public_ecapa_residual_birth_gate_row(
            &fixture,
            &rows,
            &expected_common_observations,
            &residual_policy_sha256,
            &protocol_sha256,
            gate_policy,
            gate_policy_sha256,
            &memory_observation,
        );
        assert_eq!(gate.result_sha256, public_ecapa_gate_result_sha256(&gate));
        let serialized = serialize_path_free_public_ecapa_evidence(
            &gate,
            &[
                &fixture.descriptor_path,
                &fixture.weight_path,
                &fixture.input_root,
            ],
        );
        println!("{serialized}");
        assert!(
            gate.passed,
            "residual-birth candidate did not pass its frozen public-development gate: {:?}",
            gate.failures
        );
    }

    #[test]
    #[ignore = "requires the frozen public AMI dev8 corpus and converted ECAPA weights"]
    fn external_supported_profile_redecode_same_invocation_development_gate() {
        let fixture = load_frozen_ecapa_dev8();
        let frozen_reference =
            public_supported_profile_redecode_validated_frozen_reference(&fixture);
        let gate_policy = public_supported_profile_redecode_gate_policy();
        let gate_policy_sha256 =
            super::canonical_sha256(&gate_policy).expect("hash supported-profile gate policy");
        let redecode_policy_sha256 = crate::diarization::supported_profile_redecode_policy_sha256();
        let protocol_sha256 = public_supported_profile_redecode_protocol_sha256(
            &fixture,
            &redecode_policy_sha256,
            &gate_policy_sha256,
        );
        let baseline_variant_sha256 = super::canonical_sha256(
            &crate::diarization::SUPPORTED_PROFILE_REDECODE_BASELINE_VERSION,
        )
        .expect("hash supported-profile baseline identity");
        let engines = [
            crate::model::DiarizationEngine::Ecapa,
            crate::model::DiarizationEngine::EcapaFused,
        ];
        let mut rows = Vec::with_capacity(
            usize::try_from(PUBLIC_SUPPORTED_PROFILE_REDECODE_REQUIRED_PAIR_ROWS)
                .expect("pair count fits usize"),
        );
        let mut expected_common_observations = Vec::with_capacity(rows.capacity());
        let mut expected_pair_bindings = Vec::with_capacity(rows.capacity());
        let mut memory_observation = PublicEcapaResidualBirthMemoryObservation::new();
        memory_observation.observe_stage();

        for recording_index in 0..fixture.bundle.references.len() {
            let recording = load_frozen_ecapa_recording(&fixture, recording_index);
            for (engine_index, engine) in engines.iter().copied().enumerate() {
                let (request, evidence_mode) = frozen_ecapa_request(engine);
                let preparation_started = std::time::Instant::now();
                let prepared = crate::diarization::prepare_ecapa_diarization_evaluation(
                    crate::diarization::AcousticDiarizationInput {
                        samples: &recording.samples,
                        normalized_input_sha256: &recording.normalized_input_sha256,
                        segments: &[],
                        word_aligned: false,
                        request: &request,
                        boundary_hints: &recording.boundary_hints,
                    },
                    &fixture.model,
                    &|| Ok(()),
                )
                .expect("prepare one common ECAPA observation set");
                let frozen = crate::diarization::prepare_supported_profile_redecode_evaluation(
                    &prepared,
                    || false,
                )
                .expect("freeze one incumbent partition and supported-profile topology");
                let common_preparation_wall_ns =
                    public_ecapa_duration_ns(preparation_started.elapsed());
                memory_observation.observe_stage();

                assert_eq!(
                    frozen.common_observation_sha256(),
                    prepared.common_observation_sha256()
                );
                assert!(frozen.profile_row_count() > 0);
                assert!(frozen.profile_row_count() <= gate_policy.maximum_total_profile_row_count);
                assert!(
                    frozen.forced_tracklet_count() <= frozen.tracklet_count(),
                    "forced tracklets must be a subset of all acoustic tracklets"
                );
                for digest in [
                    frozen.incumbent_partition_sha256(),
                    frozen.supported_profile_topology_sha256(),
                    frozen.frozen_support_summary_sha256(),
                    frozen.speaker_count_estimate_sha256(),
                    frozen.speaker_count_evidence_sha256(),
                    frozen.hard_hint_input_topology_sha256(),
                    frozen.overlap_input_topology_sha256(),
                    frozen.final_forced_row_output_sha256(),
                ] {
                    assert!(super::is_sha256_hex(digest));
                }

                let pair_index = recording_index
                    .saturating_mul(engines.len())
                    .saturating_add(engine_index);
                let execution_order = public_supported_profile_redecode_execution_order(pair_index);
                let (
                    (baseline_run, baseline_partition_finish_wall_ns),
                    (candidate_run, candidate_partition_finish_wall_ns),
                ) = match execution_order {
                    PublicSupportedProfileRedecodeExecutionOrder::BaselineThenCandidate => (
                        run_prepared_public_supported_profile_redecode_arm(
                            &prepared,
                            &frozen,
                            crate::diarization::SupportedProfileRedecodeMode::DisabledIncumbent,
                            &mut memory_observation,
                        ),
                        run_prepared_public_supported_profile_redecode_arm(
                            &prepared,
                            &frozen,
                            crate::diarization::SupportedProfileRedecodeMode::DevelopmentCandidateV1,
                            &mut memory_observation,
                        ),
                    ),
                    PublicSupportedProfileRedecodeExecutionOrder::CandidateThenBaseline => {
                        let candidate = run_prepared_public_supported_profile_redecode_arm(
                            &prepared,
                            &frozen,
                            crate::diarization::SupportedProfileRedecodeMode::DevelopmentCandidateV1,
                            &mut memory_observation,
                        );
                        let baseline = run_prepared_public_supported_profile_redecode_arm(
                            &prepared,
                            &frozen,
                            crate::diarization::SupportedProfileRedecodeMode::DisabledIncumbent,
                            &mut memory_observation,
                        );
                        (baseline, candidate)
                    }
                };
                let (candidate_replay_run, candidate_replay_wall_ns) =
                    run_prepared_public_supported_profile_redecode_arm(
                        &prepared,
                        &frozen,
                        crate::diarization::SupportedProfileRedecodeMode::DevelopmentCandidateV1,
                        &mut memory_observation,
                    );

                for (run, expected_mode) in [
                    (
                        &baseline_run,
                        crate::diarization::SupportedProfileRedecodeMode::DisabledIncumbent,
                    ),
                    (
                        &candidate_run,
                        crate::diarization::SupportedProfileRedecodeMode::DevelopmentCandidateV1,
                    ),
                    (
                        &candidate_replay_run,
                        crate::diarization::SupportedProfileRedecodeMode::DevelopmentCandidateV1,
                    ),
                ] {
                    run.report
                        .validate_against_request(&request, Some(recording.reference.duration_ms))
                        .expect("valid request-bound supported-profile report");
                    assert_eq!(run.report.speaker_evidence_mode, evidence_mode);
                    assert_eq!(
                        run.report.normalized_input_sha256,
                        recording.normalized_input_sha256
                    );
                    assert_eq!(run.profile_redecode.mode, expected_mode);
                    assert_eq!(run.profile_redecode.policy_sha256, redecode_policy_sha256);
                    assert_eq!(run.policy_sha256, redecode_policy_sha256);
                    assert_eq!(
                        run.common_observation_sha256,
                        frozen.common_observation_sha256()
                    );
                    assert_eq!(
                        run.incumbent_partition_sha256,
                        frozen.incumbent_partition_sha256()
                    );
                    assert_eq!(
                        run.supported_profile_topology_sha256,
                        frozen.supported_profile_topology_sha256()
                    );
                    assert_eq!(
                        run.frozen_support_summary_sha256,
                        frozen.frozen_support_summary_sha256()
                    );
                    assert!(run.profile_redecode.support_evidence_frozen_from_incumbent);
                    assert_eq!(
                        run.speaker_count_estimate_sha256,
                        frozen.speaker_count_estimate_sha256()
                    );
                    assert_eq!(
                        run.speaker_count_evidence_sha256,
                        frozen.speaker_count_evidence_sha256()
                    );
                    assert_eq!(
                        run.frozen_count_estimate_present,
                        frozen.frozen_count_estimate_present(),
                    );
                    assert_eq!(
                        run.hard_hint_input_topology_sha256,
                        frozen.hard_hint_input_topology_sha256()
                    );
                    assert_eq!(
                        run.overlap_input_topology_sha256,
                        frozen.overlap_input_topology_sha256()
                    );
                    assert_eq!(
                        run.final_forced_row_output_sha256,
                        frozen.final_forced_row_output_sha256()
                    );
                    assert_eq!(run.forced_tracklet_count, frozen.forced_tracklet_count());
                    assert_eq!(
                        run.frozen_executed_clustering_mode,
                        frozen.frozen_executed_clustering_mode(),
                    );
                    assert_eq!(
                        run.frozen_operational_partition_method,
                        frozen.frozen_operational_partition_method(),
                    );
                    assert_eq!(run.frozen_route_eligible, frozen.frozen_route_eligible());
                    assert_eq!(
                        run.profile_redecode.profile_row_count,
                        if expected_mode
                            == crate::diarization::SupportedProfileRedecodeMode::DevelopmentCandidateV1
                            && frozen.frozen_route_eligible()
                        {
                            frozen.profile_row_count()
                        } else {
                            0
                        }
                    );
                    assert_eq!(run.new_inference_count, 0);
                    assert_eq!(
                        run.frozen_count_constraints_feasible,
                        frozen.count_constraints_feasible(),
                    );
                }
                for run in [&candidate_run, &candidate_replay_run] {
                    assert!(
                        !run.profile_redecode.applied || run.clustering.constraints_satisfied,
                        "only an applied candidate must satisfy output constraints"
                    );
                    if !frozen.frozen_route_eligible() {
                        assert!(!run.profile_redecode.applied);
                        assert_eq!(
                            run.profile_redecode.fallback_reason,
                            Some(
                                crate::diarization::SupportedProfileRedecodeFallbackReason::IneligibleRoute,
                            ),
                        );
                        assert_eq!(run.profile_redecode.profile_row_count, 0);
                        assert_eq!(run.profile_redecode.supported_speaker_count, 0);
                        assert_eq!(run.profile_redecode.changed_assignment_count, 0);
                        assert!(run.profile_redecode.structural_output_sha256.is_none());
                        assert_eq!(
                            run.profile_redecode.resources,
                            crate::diarization::SupportedProfileRedecodeResourceSummary::default(),
                        );
                        assert!(
                            crate::diarization::prepared_supported_profile_redecode_outputs_identical(
                                &baseline_run,
                                run,
                            ),
                        );
                    }
                }

                let baseline_score = score_path_free_ecapa_report(
                    recording.reference,
                    &baseline_run.report,
                    &fixture.scorer_config,
                );
                let candidate_score = score_path_free_ecapa_report(
                    recording.reference,
                    &candidate_run.report,
                    &fixture.scorer_config,
                );
                let candidate_replay_score = score_path_free_ecapa_report(
                    recording.reference,
                    &candidate_replay_run.report,
                    &fixture.scorer_config,
                );
                let baseline = public_supported_profile_redecode_arm_row(
                    &baseline_run,
                    &baseline_score,
                    &baseline_variant_sha256,
                );
                let candidate = public_supported_profile_redecode_arm_row(
                    &candidate_run,
                    &candidate_score,
                    &redecode_policy_sha256,
                );
                let candidate_replay = public_supported_profile_redecode_arm_row(
                    &candidate_replay_run,
                    &candidate_replay_score,
                    &redecode_policy_sha256,
                );
                let independent_replay_matches =
                    crate::diarization::prepared_supported_profile_redecode_runs_identical(
                        &candidate_run,
                        &candidate_replay_run,
                    );
                let pair_alignment_matches = baseline_score.recording_id
                    == candidate_score.recording_id
                    && baseline_score.reference_sha256 == candidate_score.reference_sha256
                    && baseline_score.config_sha256 == candidate_score.config_sha256;
                let common_observation_matches = baseline_run.common_observation_sha256
                    == candidate_run.common_observation_sha256
                    && candidate_run.common_observation_sha256
                        == candidate_replay_run.common_observation_sha256
                    && candidate_replay_run.common_observation_sha256
                        == frozen.common_observation_sha256();
                let frozen_incumbent_matches = baseline_run.incumbent_partition_sha256
                    == candidate_run.incumbent_partition_sha256
                    && candidate_run.incumbent_partition_sha256
                        == candidate_replay_run.incumbent_partition_sha256
                    && baseline_run.supported_profile_topology_sha256
                        == candidate_run.supported_profile_topology_sha256
                    && candidate_run.supported_profile_topology_sha256
                        == candidate_replay_run.supported_profile_topology_sha256;
                let incumbent_contract_matches = !baseline_run.profile_redecode.applied
                    && baseline_run.profile_redecode.fallback_reason
                        == Some(
                            crate::diarization::SupportedProfileRedecodeFallbackReason::DisabledIncumbent,
                        )
                    && baseline_run.profile_redecode.resources
                        == crate::diarization::SupportedProfileRedecodeResourceSummary::default();
                let rejected_candidate_structural_output_matches_incumbent = !candidate_run
                    .profile_redecode
                    .applied
                    && crate::diarization::prepared_supported_profile_redecode_outputs_identical(
                        &baseline_run,
                        &candidate_run,
                    );
                let mut comparison = public_supported_profile_redecode_pair_comparison(
                    &baseline,
                    &candidate,
                    &candidate_replay,
                    pair_alignment_matches,
                    common_observation_matches,
                    frozen_incumbent_matches,
                    incumbent_contract_matches,
                    rejected_candidate_structural_output_matches_incumbent,
                );
                comparison.candidate_replay_matches &= independent_replay_matches;
                let common_observation = PublicEcapaCommonObservationBinding {
                    common_observation_schema:
                        PUBLIC_ECAPA_COMMON_OBSERVATION_BINDING_SCHEMA_VERSION.to_owned(),
                    common_observation_sha256: frozen.common_observation_sha256().to_owned(),
                    source_audio_sha256: recording.source_audio_sha256.clone(),
                    normalized_input_sha256: recording.normalized_input_sha256.clone(),
                    feature_schema_version: crate::diarization::ACOUSTIC_FEATURE_SCHEMA_VERSION
                        .to_owned(),
                    ecapa_contract_sha256: crate::ecapa_conformance::ECAPA_CONTRACT_SHA256
                        .to_owned(),
                    ecapa_package_sha256: crate::ecapa_conformance::ECAPA_PACKAGE_SHA256.to_owned(),
                    representation_provider_version:
                        crate::diarization::ECAPA_SPEAKER_REPRESENTATION_VERSION.to_owned(),
                    embedded_tracklet_count: prepared.embedded_tracklet_count(),
                };
                expected_common_observations.push(common_observation.clone());
                let mut row = PublicSupportedProfileRedecodePairRow {
                    schema_version: PUBLIC_SUPPORTED_PROFILE_REDECODE_PAIR_SCHEMA_VERSION
                        .to_owned(),
                    protocol_sha256: protocol_sha256.clone(),
                    corpus_key: fixture.bundle.corpus_key.clone(),
                    source_version: fixture.bundle.source_version.clone(),
                    evaluation_split: EvaluationSplit::Development,
                    recording_id: recording.reference.recording_id.clone(),
                    audio_duration_ms: recording.reference.duration_ms,
                    engine,
                    evidence_mode,
                    common_observation,
                    frozen_total_profile_row_count: frozen.profile_row_count(),
                    frozen_forced_tracklet_count: frozen.forced_tracklet_count(),
                    evaluation_only_frozen_forced_row_output_sha256: frozen
                        .final_forced_row_output_sha256()
                        .to_owned(),
                    baseline,
                    candidate,
                    comparison,
                    timing: PublicSupportedProfileRedecodeTiming {
                        common_preparation_wall_ns,
                        baseline_partition_finish_wall_ns,
                        candidate_partition_finish_wall_ns,
                        candidate_replay_wall_ns,
                        execution_order,
                        candidate_replay_excluded_from_gate: true,
                    },
                    deterministic_accuracy_sha256: String::new(),
                    row_sha256: String::new(),
                };
                row.deterministic_accuracy_sha256 =
                    public_supported_profile_redecode_pair_accuracy_sha256(&row);
                row.row_sha256 = public_supported_profile_redecode_pair_result_sha256(&row);
                expected_pair_bindings.push(
                    public_supported_profile_redecode_expected_pair_binding(
                        &row,
                        &recording.source_audio_sha256,
                        &frozen,
                        &baseline_score,
                        &candidate_score,
                        &candidate_replay_score,
                    ),
                );
                let serialized = serialize_path_free_public_ecapa_evidence(
                    &row,
                    &[
                        &fixture.descriptor_path,
                        &fixture.weight_path,
                        &fixture.input_root,
                        &recording.audio_path,
                    ],
                );
                println!("{serialized}");
                rows.push(row);
            }
        }

        let gate = public_supported_profile_redecode_gate_row(
            &frozen_reference,
            &rows,
            &expected_common_observations,
            &expected_pair_bindings,
            &redecode_policy_sha256,
            gate_policy,
            gate_policy_sha256,
            &memory_observation,
        );
        assert_eq!(
            gate.result_sha256,
            public_supported_profile_redecode_gate_result_sha256(&gate)
        );
        let serialized = serialize_path_free_public_ecapa_evidence(
            &gate,
            &[
                &fixture.descriptor_path,
                &fixture.weight_path,
                &fixture.input_root,
            ],
        );
        println!("{serialized}");
        assert!(
            gate.passed,
            "supported-profile candidate did not pass its frozen public-development gate: {:?}",
            gate.failures
        );
    }

    #[test]
    #[ignore = "requires external public AMI descriptor/audio and converted ECAPA weights"]
    fn external_ecapa_public_recording_reports_authoritative_score() {
        const EXPECTED_DEV8_DESCRIPTOR_SHA256: &str =
            "f99734dfe2d7441853acaa2beba6c1c3fb37e38c0593db2013d1f6c7661cd53b";
        const EXPECTED_DEV8_BUNDLE_SHA256: &str =
            "3ee85a279661b3766aaefc16de78ab0877c21ee97e7e922032bf584ade02ba79";
        const EXPECTED_SCORER_CONFIG_SHA256: &str =
            "a86fbe8d0e5fed9aff0a301857fd0d64ce9ffea49008b894818997b0c553781b";

        let descriptor_path = std::env::var_os("FRANKEN_WHISPER_ECAPA_TEST_DESCRIPTOR")
            .map(PathBuf::from)
            .expect("set FRANKEN_WHISPER_ECAPA_TEST_DESCRIPTOR")
            .canonicalize()
            .expect("canonical public descriptor");
        let weight_path = std::env::var_os("FRANKEN_WHISPER_ECAPA_TEST_WEIGHTS")
            .map(PathBuf::from)
            .expect("set FRANKEN_WHISPER_ECAPA_TEST_WEIGHTS");
        let project_root = std::env::current_dir()
            .expect("project root")
            .canonicalize()
            .expect("canonical project root");
        let input_root = descriptor_path
            .parent()
            .expect("descriptor parent")
            .canonicalize()
            .expect("canonical public input root");
        let bundle = super::materialize_public_corpus_bundle_for_split_with_cancel(
            &project_root,
            &input_root,
            &descriptor_path,
            "accept-ami-cc-by-4.0",
            Some(crate::diarization::EvaluationSplit::Development),
            Some(EXPECTED_DEV8_DESCRIPTOR_SHA256),
            || false,
        )
        .expect("validated public corpus bundle");
        assert_eq!(
            bundle.descriptor_sha256, EXPECTED_DEV8_DESCRIPTOR_SHA256,
            "public ECAPA development must use the frozen dev8 descriptor"
        );
        assert_eq!(
            bundle.bundle_sha256, EXPECTED_DEV8_BUNDLE_SHA256,
            "public ECAPA development must use the frozen dev8 bundle"
        );
        assert_eq!(bundle.references.len(), 8, "frozen dev8 recording count");
        assert_eq!(bundle.recordings.len(), bundle.references.len());
        assert_eq!(bundle.manifest.recordings.len(), bundle.references.len());

        // Re-read the exact descriptor bytes after materialization and bind the
        // path-bearing lookup map to the bundle hash. Audio is resolved only
        // through these already validated relative paths; there is no separate
        // unbound audio-path environment variable.
        let descriptor_bytes = std::fs::read(&descriptor_path).expect("read public descriptor");
        let observed_descriptor_sha256 = format!("{:x}", sha2::Sha256::digest(&descriptor_bytes));
        assert_eq!(observed_descriptor_sha256, bundle.descriptor_sha256);
        let descriptor: super::PublicCorpusInput =
            serde_json::from_slice(&descriptor_bytes).expect("parse validated public descriptor");
        let input_recordings = descriptor
            .recordings
            .into_iter()
            .map(|recording| (recording.recording_id.clone(), recording))
            .collect::<BTreeMap<_, _>>();
        assert_eq!(input_recordings.len(), bundle.references.len());

        let model = crate::ecapa_inference::EcapaModel::load(&weight_path).expect("load model");
        assert_eq!(
            model.info().contract_sha256,
            crate::ecapa_conformance::ECAPA_CONTRACT_SHA256
        );
        assert_eq!(
            model.info().package_sha256,
            crate::ecapa_conformance::ECAPA_PACKAGE_SHA256
        );
        let scorer_config = crate::diarization::DiarizationScorerConfig {
            schema_version: crate::diarization::DIARIZATION_SCORER_CONFIG_SCHEMA_VERSION.to_owned(),
            speaker_boundary_collar_ms: 250,
            change_boundary_collar_ms: 250,
            overlap_policy: crate::diarization::EvaluationOverlapPolicy::Exclude,
            calibration_bins: 10,
            count_top_k: 3,
            count_credible_mass_millionths: 900_000,
            dominant_speaker_collapse_share_millionths: 990_000,
            minimum_reference_speaker_recall_millionths: 100_000,
            minimum_effective_occupancy_ms: 250,
        };
        let scorer_config_sha256 =
            super::canonical_sha256(&scorer_config).expect("hash frozen scorer configuration");
        assert_eq!(scorer_config_sha256, EXPECTED_SCORER_CONFIG_SHA256);

        let mut emitted_rows = 0usize;
        for ((reference, recording_evidence), manifest_recording) in bundle
            .references
            .iter()
            .zip(&bundle.recordings)
            .zip(&bundle.manifest.recordings)
        {
            assert_eq!(reference.recording_id, recording_evidence.recording_id);
            assert_eq!(reference.recording_id, manifest_recording.recording_id);
            assert_eq!(
                manifest_recording.split,
                crate::diarization::EvaluationSplit::Development
            );
            let input_recording = input_recordings
                .get(&reference.recording_id)
                .expect("validated recording remains in descriptor lookup");
            let audio_path = super::canonical_relative_file(
                &input_root,
                &input_recording.audio_path,
                "ecapa_public_audio",
            )
            .expect("resolve validated public audio");
            let audio_bytes = super::read_bounded(
                &audio_path,
                super::MAX_EVALUATION_AUDIO_BYTES,
                "ecapa_public_audio",
            )
            .expect("read bounded public WAV");
            let observed_audio_sha256 = format!("{:x}", sha2::Sha256::digest(&audio_bytes));
            assert_eq!(
                observed_audio_sha256, recording_evidence.audio_sha256,
                "audio changed after bundle validation"
            );
            let samples = crate::native_engine::decode::read_wav_16k_mono(&audio_bytes)
                .expect("decode public WAV");
            let decoded_duration_ms = u64::try_from(samples.len()).expect("sample count fits") / 16;
            assert!(reference.duration_ms > 0, "public recording is empty");
            assert!(
                decoded_duration_ms.abs_diff(reference.duration_ms) <= 1,
                "decoded and reference durations differ by more than one millisecond: decoded={decoded_duration_ms} reference={}",
                reference.duration_ms,
            );
            let normalized_input_sha256 = super::hash_pcm_prefix(&samples);
            let boundary_hints = crate::diarization::AcousticBoundaryHints {
                speech_regions_ms: super::merged_scored_speech_regions(
                    &reference.turns,
                    &reference.ignored_regions,
                ),
                ..crate::diarization::AcousticBoundaryHints::default()
            };

            // Raw ECAPA distance characterization is representation-only and
            // therefore computed once per recording, not once per fusion mode.
            let observations = crate::diarization::ecapa_tracklet_evaluation_observations(
                &samples,
                &boundary_hints,
                &model,
                &|| Ok(()),
            )
            .expect("ECAPA public-development observations");
            let mut ambiguous_tracklet_count = 0usize;
            let labeled_observations = observations
                .iter()
                .filter_map(|observation| {
                    let mut overlap_by_speaker = BTreeMap::<String, u64>::new();
                    for turn in &reference.turns {
                        let Some(speaker) = turn.speaker.as_ref() else {
                            continue;
                        };
                        let overlap_start = observation.start_ms.max(turn.start_ms);
                        let overlap_end = observation.end_ms.min(turn.end_ms);
                        let overlap = overlap_end.saturating_sub(overlap_start);
                        if overlap > 0 {
                            *overlap_by_speaker.entry(speaker.clone()).or_default() += overlap;
                        }
                    }
                    let covered_ms = overlap_by_speaker.values().copied().sum::<u64>();
                    let duration_ms = observation.end_ms.saturating_sub(observation.start_ms);
                    let dominant = overlap_by_speaker.into_iter().max_by(|left, right| {
                        left.1.cmp(&right.1).then_with(|| right.0.cmp(&left.0))
                    });
                    let Some((speaker, dominant_ms)) = dominant else {
                        ambiguous_tracklet_count += 1;
                        return None;
                    };
                    if duration_ms == 0
                        || covered_ms.saturating_mul(5) < duration_ms.saturating_mul(4)
                        || dominant_ms.saturating_mul(5) < covered_ms.saturating_mul(4)
                    {
                        ambiguous_tracklet_count += 1;
                        return None;
                    }
                    Some((speaker, &observation.embedding))
                })
                .collect::<Vec<_>>();
            let mut same_distances = Vec::<f32>::new();
            let mut different_distances = Vec::<f32>::new();
            for left in 0..labeled_observations.len() {
                for right in left + 1..labeled_observations.len() {
                    let Some(distance) = crate::diarization::ecapa_evaluation_cosine_distance(
                        labeled_observations[left].1,
                        labeled_observations[right].1,
                    ) else {
                        continue;
                    };
                    if labeled_observations[left].0 == labeled_observations[right].0 {
                        same_distances.push(distance);
                    } else {
                        different_distances.push(distance);
                    }
                }
            }
            same_distances.sort_by(f32::total_cmp);
            different_distances.sort_by(f32::total_cmp);
            let quantile = |values: &[f32], numerator: usize| {
                (!values.is_empty()).then(|| {
                    let index = values.len().saturating_sub(1).saturating_mul(numerator) / 10;
                    values[index]
                })
            };
            let pair_distance_summary = serde_json::json!({
                "embedded_tracklets": observations.len(),
                "labeled_tracklets": labeled_observations.len(),
                "ambiguous_tracklets": ambiguous_tracklet_count,
                "same_pair_count": same_distances.len(),
                "same_p10": quantile(&same_distances, 1),
                "same_p50": quantile(&same_distances, 5),
                "same_p90": quantile(&same_distances, 9),
                "different_pair_count": different_distances.len(),
                "different_p10": quantile(&different_distances, 1),
                "different_p50": quantile(&different_distances, 5),
                "different_p90": quantile(&different_distances, 9),
            });

            for engine in [
                crate::model::DiarizationEngine::Ecapa,
                crate::model::DiarizationEngine::EcapaFused,
            ] {
                let expected_evidence_mode = match engine {
                    crate::model::DiarizationEngine::Ecapa => {
                        crate::model::DiarizationSpeakerEvidenceMode::EcapaOnly
                    }
                    crate::model::DiarizationEngine::EcapaFused => {
                        crate::model::DiarizationSpeakerEvidenceMode::EcapaWithAcousticChannel
                    }
                    _ => unreachable!("the frozen ECAPA mode list is exhaustive"),
                };
                let request = crate::model::DiarizationRequest {
                    engine,
                    fallback: crate::model::DiarizationFallbackPolicy::Unknown,
                    speaker_count: crate::model::SpeakerCountRequest::Infer,
                    ..crate::model::DiarizationRequest::default()
                };
                let started = std::time::Instant::now();
                let (report, _) = crate::diarization::diarize_ecapa_pcm(
                    crate::diarization::AcousticDiarizationInput {
                        samples: &samples,
                        normalized_input_sha256: &normalized_input_sha256,
                        segments: &[],
                        word_aligned: false,
                        request: &request,
                        boundary_hints: &boundary_hints,
                    },
                    &model,
                    &|| Ok(()),
                )
                .expect("native ECAPA common-stack diarization");
                let wall_time_ms = u64::try_from(started.elapsed().as_millis())
                    .unwrap_or(u64::MAX)
                    .max(1);
                let peak_rss_bytes = super::sampled_process_rss_bytes();
                report
                    .validate_against_request(&request, Some(reference.duration_ms))
                    .expect("valid request-bound native ECAPA report");
                assert_eq!(report.speaker_evidence_mode, expected_evidence_mode);
                let representation = report
                    .neural_representation
                    .as_ref()
                    .expect("neural representation summary");
                assert!(representation.embedded_tracklet_count > 0);
                assert_eq!(
                    representation.provider_version,
                    crate::diarization::ECAPA_SPEAKER_REPRESENTATION_VERSION
                );
                assert_eq!(
                    representation.loaded_model_package_sha256.as_deref(),
                    Some(crate::ecapa_conformance::ECAPA_PACKAGE_SHA256)
                );
                assert_eq!(
                    representation.expected_model_package_sha256,
                    crate::ecapa_conformance::ECAPA_PACKAGE_SHA256
                );
                assert_eq!(
                    representation.model_load_source,
                    Some(crate::model::NeuralModelLoadSource::PackageVerified)
                );
                assert_eq!(report.normalized_input_sha256, normalized_input_sha256);
                let speaker_pair_calibration_sha256 =
                    crate::diarization::ecapa_speaker_pair_calibration_sha256(
                        expected_evidence_mode,
                    );
                let count_estimate = report
                    .speaker_count
                    .estimate
                    .as_ref()
                    .expect("ECAPA common stack must retain its count evidence");
                assert_eq!(
                    count_estimate.calibration_sha256,
                    speaker_pair_calibration_sha256
                );

                // Accuracy authority deliberately excludes timing/RSS so the
                // hypothesis and score hashes are deterministic. Runtime is
                // retained separately below as diagnostic-only evidence.
                let hypothesis = crate::diarization::DiarizationHypothesisDocument {
                    schema_version: crate::diarization::DIARIZATION_HYPOTHESIS_SCHEMA_VERSION
                        .to_owned(),
                    recording_id: reference.recording_id.clone(),
                    duration_ms: reference.duration_ms,
                    turns: report
                        .turns
                        .iter()
                        .map(|turn| crate::diarization::EvaluationTurn {
                            start_ms: turn.start_ms,
                            end_ms: turn.end_ms,
                            speaker: turn.speaker_ref.clone(),
                            speaker_confidence: turn.speaker_confidence,
                            overlap_suspected: turn.overlap_suspected,
                        })
                        .collect(),
                    speaker_count_estimate: report.speaker_count.estimate.clone(),
                    performance: None,
                };
                let score = crate::diarization::score_diarization_documents(
                    reference,
                    &hypothesis,
                    &scorer_config,
                )
                .expect("authoritative public-corpus score");
                crate::diarization::verify_authoritative_score_hash(&score)
                    .expect("valid authoritative score hash");
                assert!(score.performance.is_none());
                assert!(score.diarization.der.is_some());
                assert_eq!(score.config_sha256, scorer_config_sha256);
                let report_sha256 =
                    super::canonical_sha256(&report).expect("hash native ECAPA report");
                let audio_duration_sec = reference.duration_ms as f64 / 1_000.0;
                let diagnostic_real_time_factor =
                    wall_time_ms as f64 / 1_000.0 / audio_duration_sec;
                let protocol = serde_json::json!({
                    "oracle_vad": true,
                    "oracle_speaker_count": false,
                    "speaker_count_request": &request.speaker_count,
                    "fallback_policy": request.fallback,
                    "accuracy_score_includes_performance": false,
                });
                let provenance = serde_json::json!({
                    "descriptor_sha256": &bundle.descriptor_sha256,
                    "bundle_sha256": &bundle.bundle_sha256,
                    "audio_sha256": &recording_evidence.audio_sha256,
                    "annotation_sha256": &recording_evidence.annotation_sha256,
                    "normalized_input_sha256": &report.normalized_input_sha256,
                    "reference_sha256": &score.reference_sha256,
                    "hypothesis_sha256": &score.hypothesis_sha256,
                    "report_sha256": report_sha256,
                    "scorer_version": &score.scorer_version,
                    "scorer_config_sha256": &score.config_sha256,
                    "ecapa_contract_sha256": crate::ecapa_conformance::ECAPA_CONTRACT_SHA256,
                    "ecapa_package_sha256": crate::ecapa_conformance::ECAPA_PACKAGE_SHA256,
                    "speaker_pair_calibration_sha256": speaker_pair_calibration_sha256,
                });
                let representation_evidence = serde_json::json!({
                    "schema_version": &representation.schema_version,
                    "provider_version": &representation.provider_version,
                    "status": representation.status,
                    "model_load_source": representation.model_load_source,
                    "embedded_tracklets": representation.embedded_tracklet_count,
                    "zero_padded_tracklets": representation.zero_padded_tracklet_count,
                    "skipped_tracklets": representation.skipped_tracklet_count,
                });
                let accuracy = serde_json::json!({
                    "der": score.diarization.der,
                    "jer": score.diarization.jer,
                    "reference_speaker_time_sec": score.diarization.reference_speaker_time_sec,
                    "missed_speech_sec": score.diarization.missed_speech_sec,
                    "false_alarm_sec": score.diarization.false_alarm_sec,
                    "speaker_confusion_sec": score.diarization.speaker_confusion_sec,
                    "scored_duration_sec": score.scored_duration_sec,
                    "selective_coverage": score.selective_attribution.coverage,
                    "selective_risk": score.selective_attribution.selective_risk,
                    "dominant_speaker_share": score.speaker_occupancy.dominant_speaker_share,
                    "unknown_speaker_share": score.speaker_occupancy.unknown_speaker_share,
                    "score_sha256": &score.result_sha256,
                });
                let speaker_count_evidence = serde_json::json!({
                    "reference_speakers": score.speaker_count.reference_speakers,
                    "hypothesis_speakers": score.speaker_count.hypothesis_speakers,
                    "effective_speakers": score.speaker_occupancy.effective_speaker_count,
                    "absolute_error": score.speaker_count.absolute_error,
                    "exact_match": score.speaker_count.absolute_error == 0,
                    "status": report.speaker_count.status,
                    "selected": count_estimate.selected_count,
                    "unresolved_probability": count_estimate.unresolved_probability,
                    "posterior_map": score.speaker_count_posterior.map_count,
                    "lanes": &count_estimate.lanes,
                    "speaker_evidence": &report.speaker_count.speaker_evidence,
                });
                let diagnostics = serde_json::json!({
                    "operational_partition": &report.operational_partition,
                    "fallback_status": report.fallback_status,
                    "turn_count": report.turns.len(),
                    "pair_distance_summary": &pair_distance_summary,
                    "wall_time_ms": wall_time_ms,
                    "peak_rss_bytes": peak_rss_bytes,
                    "real_time_factor": diagnostic_real_time_factor,
                    "performance_authority": "single-ordered-process-observation",
                });
                let row = serde_json::json!({
                    "schema_version": "public-ecapa-development-row-v1",
                    "corpus_key": &bundle.corpus_key,
                    "source_version": &bundle.source_version,
                    "evaluation_split": manifest_recording.split,
                    "recording_id": &score.recording_id,
                    "audio_duration_ms": reference.duration_ms,
                    "engine": engine,
                    "speaker_evidence_mode": report.speaker_evidence_mode,
                    "protocol": protocol,
                    "provenance": provenance,
                    "representation": representation_evidence,
                    "accuracy": accuracy,
                    "speaker_count": speaker_count_evidence,
                    "diagnostics": diagnostics,
                });
                let serialized = serde_json::to_string(&row)
                    .expect("serialize path-free public ECAPA development row");
                for local_path in [&descriptor_path, &audio_path, &weight_path] {
                    assert!(
                        !serialized.contains(local_path.to_string_lossy().as_ref()),
                        "public ECAPA development row retained a local path"
                    );
                }
                println!("{serialized}");
                emitted_rows += 1;
            }
        }
        assert_eq!(emitted_rows, 16, "two explicit modes across frozen dev8");
    }

    fn private_tempdir(label: &str) -> tempfile::TempDir {
        let directory = tempdir().unwrap_or_else(|error| panic!("{label}: {error}"));
        #[cfg(any(target_os = "linux", target_os = "android", target_vendor = "apple"))]
        {
            use std::os::unix::fs::PermissionsExt as _;

            std::fs::set_permissions(directory.path(), std::fs::Permissions::from_mode(0o700))
                .unwrap_or_else(|error| panic!("private {label}: {error}"));
        }
        directory
    }

    fn create_private_directory(path: &Path) {
        std::fs::create_dir(path).expect("fixture directory");
        #[cfg(any(target_os = "linux", target_os = "android", target_vendor = "apple"))]
        {
            use std::os::unix::fs::PermissionsExt as _;

            std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o700))
                .expect("private fixture directory");
        }
    }

    #[cfg(any(target_os = "linux", target_os = "android", target_vendor = "apple"))]
    struct AlwaysFailsSerialization;

    #[cfg(any(target_os = "linux", target_os = "android", target_vendor = "apple"))]
    impl Serialize for AlwaysFailsSerialization {
        fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
        where
            S: serde::Serializer,
        {
            let mut state = serializer.serialize_struct("SensitiveFixture", 2)?;
            state.serialize_field("sensitive", "must-not-survive")?;
            Err(<S::Error as serde::ser::Error>::custom(
                "intentional failure after a serialized field",
            ))
        }
    }

    fn write_wave(path: &Path, sample_rate: u32, channels: u16, frames: u32) {
        let spec = hound::WavSpec {
            channels,
            sample_rate,
            bits_per_sample: 16,
            sample_format: hound::SampleFormat::Int,
        };
        let mut writer = hound::WavWriter::create(path, spec).expect("WAV");
        for _ in 0..frames * u32::from(channels) {
            writer.write_sample(0_i16).expect("sample");
        }
        writer.finalize().expect("finalize WAV");
    }

    fn sha256(path: &Path) -> String {
        format!(
            "{:x}",
            sha2::Sha256::digest(std::fs::read(path).expect("fixture"))
        )
    }

